import { TM_EMOJI, TM_EMOJI_CATEGORIES, type TmEmoji, type TmEmojiCategory } from '@/lib/tm-emoji-data';

// TableMeet's own chat emoji (assets/emoji, generated by scripts/gen-emoji.mjs). Messages store the emoji character
// each one stands for (😂, 🍜, …), so notifications, the inbox and other apps read normally; chats draw the
// TableMeet picture wherever such a character appears, also when it was typed on the phone's own emoji keyboard.
// Greetings have no character and are stored as ":tm_<id>:" stickers. Reactions store the id (chat_reactions).

export { TM_EMOJI, TM_EMOJI_CATEGORIES, type TmEmoji, type TmEmojiCategory };

const VS16 = '️';
const ZWJ = '‍';

export const EMOJI_BY_ID = new Map(TM_EMOJI.map((emoji) => [emoji.id, emoji]));
const BY_CHAR = new Map(TM_EMOJI.filter((emoji) => emoji.char).map((emoji) => [emoji.char!.replace(VS16, ''), emoji]));

// The quick reactions offered when pressing and holding a message.
export const QUICK_REACTIONS = ['heart', 'lol', 'wow', 'sad', 'thumbs', 'fire'] as const;

// The categories that go into text and reactions: all but the greetings (stickers on their own; the server checks
// the same list of reactions).
export const TEXT_EMOJI_CATEGORIES = TM_EMOJI_CATEGORIES.filter((category) => category !== 'greetings');

export function emojiByCategory(category: TmEmojiCategory): TmEmoji[] {
  return TM_EMOJI.filter((emoji) => emoji.category === category);
}

// What a picked emoji adds to a message: its character, or the sticker code for a greeting.
export function emojiText(emoji: TmEmoji): string {
  return emoji.char ?? `:tm_${emoji.id}:`;
}

export type TextPart = { text: string } | { emoji: TmEmoji };

function isSkinTone(char: string | undefined): boolean {
  const code = char?.codePointAt(0) ?? 0;
  return code >= 0x1f3fb && code <= 0x1f3ff;
}

// Splits message text into plain text and TableMeet emoji. A character that is part of a longer emoji (a skin tone,
// or a sequence joined with ZWJ such as ❤️‍🔥) stays the phone's own emoji.
export function parseEmojiText(body: string): TextPart[] {
  const parts: TextPart[] = [];
  let text = '';
  const flush = () => {
    if (text) parts.push({ text });
    text = '';
  };
  for (const piece of body.split(/(:tm_[a-z]+:)/)) {
    const sticker = /^:tm_([a-z]+):$/.exec(piece);
    const stickerEmoji = sticker ? EMOJI_BY_ID.get(sticker[1]) : undefined;
    if (stickerEmoji) {
      flush();
      parts.push({ emoji: stickerEmoji });
      continue;
    }
    const chars = Array.from(piece);
    for (let i = 0; i < chars.length; i++) {
      const emoji = BY_CHAR.get(chars[i]);
      if (emoji) {
        const end = chars[i + 1] === VS16 ? i + 2 : i + 1;
        if (chars[i - 1] !== ZWJ && chars[end] !== ZWJ && !isSkinTone(chars[end])) {
          flush();
          parts.push({ emoji });
          i = end - 1;
          continue;
        }
      }
      text += chars[i];
    }
  }
  flush();
  return parts;
}

// A message that is only 1–3 TableMeet emoji (spaces allowed) is shown big and animated, without a bubble.
export function bigEmoji(parts: TextPart[]): TmEmoji[] | null {
  const emoji: TmEmoji[] = [];
  for (const part of parts) {
    if ('emoji' in part) emoji.push(part.emoji);
    else if (part.text.trim()) return null;
  }
  return emoji.length >= 1 && emoji.length <= 3 ? emoji : null;
}

// Greeting words that read differently in Thai (the rest are the foreign word in both languages).
const GREETINGS_TH: Record<string, string> = { sawasdee: 'สวัสดี' };

// The word on a greeting sticker, for previews and screen readers.
export function greetingWord(emoji: TmEmoji, language: string): string {
  return (language === 'th' && GREETINGS_TH[emoji.id]) || emoji.name;
}

// Message text for one-line previews (inbox, notifications): greeting stickers become "👋 Sawasdee", like the
// phone notifications (push_preview in the database).
export function emojiPreview(body: string, language: string): string {
  return body.replace(/:tm_([a-z]+):/g, (code, id: string) => {
    const emoji = EMOJI_BY_ID.get(id);
    return emoji ? `👋 ${greetingWord(emoji, language)}` : code;
  });
}

// Whether a message holds a greeting sticker (its text can't be edited in the composer).
export function hasSticker(body: string): boolean {
  return /:tm_[a-z]+:/.test(body);
}
